<?php require_once 'includes/config.php'; if(!empty($_SESSION['user_id'])) redirect('user_dashboard.php'); $error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';$confirm=$_POST['confirm_password']??''; if(strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<6||$pass!==$confirm)$error='Use a valid name/email, a 6+ character password, and matching confirmation.';else{$c=$conn->prepare('SELECT id FROM users WHERE email=?');$c->bind_param('s',$email);$c->execute();$c->store_result();if($c->num_rows)$error='An account with this email already exists.';else{$hash=password_hash($pass,PASSWORD_DEFAULT);$s=$conn->prepare('INSERT INTO users(name,email,password) VALUES(?,?,?)');$s->bind_param('sss',$name,$email,$hash);$s->execute();$_SESSION['user_id']=$conn->insert_id;$_SESSION['user_name']=$name;session_regenerate_id(true);redirect('user_dashboard.php');}$c->close();}}
$title='Create Account'; require 'includes/header.php'; ?><div class="page"><section class="card"><h1>Create account</h1><p class="subtitle">Create your account to report and track issues.</p><?php if($error):?><div class="alert alert-error"><?=e($error)?></div><?php endif;?><form method="post"><div class="field"><label>Full name</label><input name="name" required value="<?=e($_POST['name']??'')?>"></div><div class="field"><label>Email</label><input type="email" name="email" required value="<?=e($_POST['email']??'')?>"></div><div class="field"><label>Password</label><input type="password" name="password" minlength="6" required></div><div class="field"><label>Confirm password</label><input type="password" name="confirm_password" minlength="6" required></div><button class="btn btn-primary" style="width:100%">Create account</button></form><p class="muted">Already registered? <a href="login.php">Sign in</a></p></section></div><?php require 'includes/footer.php'; ?>
